{"t":"nhl","id":"nhlconn-004","h":"ac88f7ff31e48b14f029353362f56e27","n":[{"theme":"Played for the Canadiens","players":["P.K. Subban","Shea Weber","Brendan Gallagher","Nick Suzuki","Cole Caufield"],"difficulty":"yellow"},{"theme":"Played for the Panthers","players":["Matthew Tkachuk","Aleksander Barkov","Sam Reinhart","Carter Verhaeghe","Aaron Ekblad"],"difficulty":"green"},{"theme":"Played for the Sharks","players":["Macklin Celebrini","Marc-Edouard Vlasic","Evander Kane","Logan Couture","Tomáš Hertl"],"difficulty":"blue"},{"theme":"1,000+ career points","players":["Connor McDavid","Leon Draisaitl","Nikita Kucherov","Nathan MacKinnon","Steven Stamkos"],"difficulty":"purple"}]}
]$pl$;
  rec record;
  rewritten int := 0;
  already int := 0;
  drifted text[] := '{}';
  cnt int;
begin
  if md5(payload) <> '08f17453e4e0f25f4741b2269adbce01' then
    raise exception 'Round 1558: payload checksum mismatch, nothing applied';
  end if;
  for rec in select * from jsonb_to_recordset(payload::jsonb) as x(t text, id text, h text, n jsonb) loop
    if (rec.t = 'baseball' and exists (select 1 from public.baseball_connections_puzzles c where c.puzzle_id = rec.id and c.groups_json = rec.n)) or (rec.t = 'nfl' and exists (select 1 from public.nfl_connections_puzzles c where c.puzzle_id = rec.id and c.groups_json = rec.n)) or (rec.t = 'nhl' and exists (select 1 from public.nhl_connections_puzzles c where c.puzzle_id = rec.id and c.groups_json = rec.n)) then
      already := already + 1;
    else
      if rec.t = 'baseball' then
      update public.baseball_connections_puzzles c set groups_json = rec.n where c.puzzle_id = rec.id and md5(c.groups_json::text) = rec.h;
      elsif rec.t = 'nfl' then
      update public.nfl_connections_puzzles c set groups_json = rec.n where c.puzzle_id = rec.id and md5(c.groups_json::text) = rec.h;
      elsif rec.t = 'nhl' then
      update public.nhl_connections_puzzles c set groups_json = rec.n where c.puzzle_id = rec.id and md5(c.groups_json::text) = rec.h;
      else
        raise exception 'Round 1558: unknown table %', rec.t;
      end if;
      get diagnostics cnt = row_count;
      if cnt > 0 then rewritten := rewritten + 1; else drifted := drifted || (rec.t || ':' || rec.id); end if;
    end if;
  end loop;
  if rewritten + already <> 37 then
    raise exception 'Round 1558: % rewritten, % already current, drifted %: nothing applied', rewritten, already, drifted;
  end if;
  raise notice 'Round 1558: % rewritten, % already current, 0 drifted', rewritten, already;
end
$$;
